import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"기록","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/history.md","filePath":"ko-KR/user-guide/settings/history.md","lastUpdated":1786537234000}'),s={name:"ko-KR/user-guide/settings/history.md"};function n(i,t,l,d,c,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="기록" tabindex="-1">기록 <a class="header-anchor" href="#기록" aria-label="Permalink to &quot;기록&quot;">​</a></h1><p>각각 독립적인 두 개의 탭: <strong>검색 기록</strong>과 <strong>키워드 기록</strong>입니다.</p><h2 id="검색-기록" tabindex="-1">검색 기록 <a class="header-anchor" href="#검색-기록" aria-label="Permalink to &quot;검색 기록&quot;">​</a></h2><p>실제로 열었던 결과를 추적하여, 다음에 비슷한 것을 검색할 때 우선순위를 높일 수 있게 합니다.</p><p>검색 기록은 열었던 경로와 그 경로로 이어진 검색어를 함께 기억합니다. 나중에 기록된 검색어와 퍼지 일치하는 쿼리를 입력하면 퀵, 인라인, 전체 검색 창에서 아직 존재하는 경로를 다시 불러와 우선 표시할 수 있습니다. 예를 들어 <code>bcomp</code>로 <code>BCompare.exe</code>를 연 뒤에는 <code>bc</code>만 입력해도 위쪽에 다시 나타납니다. 인라인 검색에서는 활성 폴더 안의 일치 항목을 <strong>현재 폴더</strong>에, 나머지를 <strong>전역 검색</strong>에 표시합니다. 존재하지 않는 경로는 무시되며 같은 경로는 한 번만 표시됩니다.</p><ul><li><strong>기록 활성화</strong> 체크박스 — 추적을 켜고 끕니다. 비활성화해도 기존 항목은 유지되며, 다만 더 이상 추가되지 않을 뿐입니다.</li><li><strong>검색 상자</strong> — 표시되는 기록 목록을 키워드로 필터링합니다.</li><li>각 항목은 개별적으로 삭제하거나, <strong>모든 기록 지우기</strong>로 한 번에 삭제할 수 있습니다.</li></ul><h2 id="키워드-기록" tabindex="-1">키워드 기록 <a class="header-anchor" href="#키워드-기록" aria-label="Permalink to &quot;키워드 기록&quot;">​</a></h2><p>퀵 창의 검색 상자에 입력했던 원문 텍스트를 추적합니다(열었던 것이 아니라). 이를 통해 <a href="./../hotkeys.html#전역-단축키">키워드 기록 단축키</a>(기본값 <code>Alt+Up</code> / <code>Alt+Down</code>)로 최근 쿼리를 거슬러 순환할 수 있습니다.</p><ul><li>동일한 <strong>기록 활성화</strong> 토글, 검색 필터, 항목별 삭제, <strong>모든 기록 지우기</strong> 버튼이 있으며, 대상이 열었던 결과가 아니라 키워드로 한정됩니다.</li></ul>',9)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
